import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagsPickerProps {
  defaultTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

function ArticleTagsPicker({
  defaultTags = [],
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagsPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const handleValueChange = useCallback(
    (next: string[]) => {
      const normalized = next
        .map((tag) => tag.trim())
        .filter((tag, index, all) => tag.length > 0 && all.indexOf(tag) === index);
      commit(normalized);
    },
    [commit],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((item) => item !== tag));
    },
    [commit, tags],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder={placeholder}
        value={tags}
        onValueChange={handleValueChange}
      />

      {tags.length > 0 ? (
        <ul
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: '8px',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li key={tag} style={{ display: 'flex', maxWidth: '100%' }}>
              <JxChip
                active
                removable
                onRemove={() => removeTag(tag)}
                title={tag}
                style={{
                  maxWidth: '100%',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {tag}
              </JxChip>
            </li>
          ))}
        </ul>
      ) : (
        <p
          style={{
            margin: 0,
            font: 'inherit',
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
            color: 'var(--jx-text-2)',
          }}
        >
          Пока ни одного тега. Наберите слово в поле выше и нажмите Enter — тег появится здесь.
        </p>
      )}
    </div>
  );
}

export default ArticleTagsPicker;

